import time
from collections.abc import Callable
from enum import Enum
from typing import Any, Dict, Optional, TYPE_CHECKING

import boto3.session
from langchain_community.vectorstores import OpenSearchVectorSearch
from opensearchpy import RequestsHttpConnection, AWSV4SignerAuth, OpenSearch
from opensearchpy.exceptions import RequestError

from dataiku.core.vector_stores.dku_vector_store import DkuRemoteVectorStore, DistanceMetric, logger, RecordManagerCleanupMode
from dataiku.core.vector_stores.elasticsearch_vector_store import ElasticSearchVectorStoreDocumentFilter
from dataiku.langchain.dataset_loader import VectorStoreLoader
from dataiku.llm.types import RetrievableKnowledge
from dataikuapi.dss.admin import DSSConnectionInfo
from dataikuapi.dss.langchain import DKUEmbeddings

if TYPE_CHECKING:
    from langchain_core.vectorstores import VectorStore

class AWSServiceType(str, Enum):
    OPENSEARCH_SERVERLESS = 'aoss'
    OPENSEARCH_HOSTED = 'es'


class OpenSearchVectorStore(DkuRemoteVectorStore):
    DEFAULT_REQUIRED_FIELD_NAMES = {
        "content": "text",
        "vector": "vector_field",
    }

    # Keep in sync with ElasticSearchConnection class on java side
    DEFAULT_WAIT_DELAY_SECONDS: float = 20  # DEFAULT_REFRESH_WAIT_DELAY_MS in java
    DEFAULT_MAX_WAIT_DELAY_SECONDS: float = 90  # DEFAULT_REFRESH_WAIT_MAX_DELAY_MS in java
    DEFAULT_INDEX_ENGINE_PRE_3 = "nmslib"
    DEFAULT_INDEX_ENGINE_3_PLUS = "faiss"
    INDEX_ENGINE_DKU_PROPERTY = "dku.connection.opensearch.knnEngine"
    SUPPORTED_INDEX_ENGINES = {"faiss", "lucene", "nmslib"}

    def __init__(self, kb: RetrievableKnowledge, exec_folder: str, connection_info_retriever: Callable[[str], DSSConnectionInfo]):
        self.opensearch_url: Optional[str] = None
        self.auth_kwargs: Dict = {}
        self.is_amazon_opensearch_serverless = False
        self.wait_delay_s = self.DEFAULT_WAIT_DELAY_SECONDS
        self.max_wait_delay_s = self.DEFAULT_MAX_WAIT_DELAY_SECONDS
        self.version = (0, 0)
        self.engine = self.DEFAULT_INDEX_ENGINE_PRE_3
        super(OpenSearchVectorStore, self).__init__(kb, exec_folder, connection_info_retriever, bulk_size=500)  # OpenSearch default limit bulk size
        self.document_filter = ElasticSearchVectorStoreDocumentFilter(
            self.metadata_column_type_and_meaning,
            use_metadata_prefix=self.kb.get("managed", True),
        )

    def set_index_name(self, index_name: str) -> None:
        self.index_name = index_name.lower()

    def init_connection(self) -> None:
        connection_info = self.connection_info_retriever(self.connection_name)
        connection_params = connection_info.get_params()
        self.set_wait_properties(connection_params)
        auth_type = connection_params['authType']
        self.auth_kwargs = {}
        scheme = "http"
        if connection_params['ssl']:
            scheme = "https"
            if connection_params['trustAnySSLCertificate']:
                self.auth_kwargs['verify_certs'] = False

        self.opensearch_url = "{}://{}:{}".format(scheme, connection_params['host'], connection_params['port'])
        if auth_type == "NONE":
            pass
        elif auth_type == "PASSWORD":
            self.auth_kwargs['http_auth'] = (connection_params['username'], connection_params['password'])
        elif auth_type == "OAUTH2_APP":
            raise NotImplementedError("We do not support OAuth v2.0 for Knowledge Banks")
        elif auth_type in ["AWS_KEYPAIR", "AWS_ENVIRONMENT", "AWS_STS", "AWS_CUSTOM"]:
            # always use sessions provided on Java side to ensure that we have the same behaviour
            # TODO not possible
            credentials = connection_info.get_aws_credential()
            session = boto3.session.Session(
                aws_access_key_id=credentials['accessKey'],
                aws_secret_access_key=credentials['secretKey'],
                aws_session_token=credentials.get('sessionToken')
            ).get_credentials()
            self.set_aws_connection(session, connection_params)
        else:
            raise ValueError("Unknown authentication type: " + auth_type)

        self.version = self._fetch_version()
        self.set_engine_property(connection_params)

    def set_aws_connection(self, session: boto3.session.Session, connection_params: Dict) -> None:
        service_name = AWSServiceType[connection_params['aws']['service']].value
        self.auth_kwargs['http_auth'] = AWSV4SignerAuth(session, connection_params['aws']['region'], service_name)
        self.auth_kwargs['connection_class'] = RequestsHttpConnection
        self.is_amazon_opensearch_serverless = service_name == "aoss"
        if self.is_amazon_opensearch_serverless:
            # AOSS fails without _large enough_ read http timeout, so let's use a larger value based on wait_delay_s
            self.auth_kwargs['timeout'] = self.wait_delay_s * 5

    def set_wait_properties(self, connection_params: Dict) -> None:
        for property in connection_params.get('dkuProperties', []):
            if property['name'] == "dku.connection.elasticsearch.refreshWaitDelayMs":
                self.wait_delay_s = int(property['value']) / 1000.0
                logger.info("Set custom wait delay: {}s".format(self.wait_delay_s))
            elif property['name'] == "dku.connection.elasticsearch.refreshMaxWaitDelayMs":
                self.max_wait_delay_s = int(property['value']) / 1000.0
                logger.info("Set custom max wait delay: {}s".format(self.max_wait_delay_s))

    def set_engine_property(self, connection_params: Dict) -> None:
        self.engine = self.get_index_engine_from_connection_params(connection_params, self.version)

    @classmethod
    def get_default_index_engine_for_version(cls, version: tuple[int, int]) -> str:
        if version >= (3, 0):
            return cls.DEFAULT_INDEX_ENGINE_3_PLUS
        return cls.DEFAULT_INDEX_ENGINE_PRE_3

    @classmethod
    def get_index_engine_from_connection_params(cls, connection_params: Dict, version: tuple[int, int]) -> str:
        engine = cls.get_default_index_engine_for_version(version)
        for property in connection_params.get('dkuProperties', []):
            if property['name'] != cls.INDEX_ENGINE_DKU_PROPERTY:
                continue
            property_value = property.get('value', '')
            normalized_value = property_value.strip().lower()
            if normalized_value in cls.SUPPORTED_INDEX_ENGINES:
                engine = normalized_value
                logger.info("Set custom OpenSearch index engine from connection property: {}".format(engine))
            else:
                logger.warning(
                    "Ignoring invalid value for OpenSearch index engine connection property "
                    "(expected one of {}): {}".format(sorted(cls.SUPPORTED_INDEX_ENGINES), property_value)
                )
        return engine

    def _fetch_version(self) -> tuple[int, int]:
        client = OpenSearch(
            hosts=[self.opensearch_url],
            **self.auth_kwargs
        )
        try:
            version_number = client.info()["version"]["number"]
            logger.info("Connected to OpenSearch v{}".format(version_number))
            version_parts = version_number.split(".")
            return int(version_parts[0]), int(version_parts[1])
        except Exception as e:
            raise ConnectionError("Could not retrieve OpenSearch version: {}".format(e))

    def _get_search_kwargs(self, query_settings) -> Dict:
        field_names = self._get_required_field_names()
        return {
            **super()._get_search_kwargs(query_settings),
            "vector_field": field_names["vector"],
            "text_field": field_names["content"],
        }

    def get_db(self, embeddings: Optional[DKUEmbeddings], allow_creation: bool = False, **kwargs: Any) -> OpenSearchVectorSearch:
        # todo should check if index already exist to raise an error if allow_creation=false first (langchain always create it by default if unfound)
        field_names = self._get_required_field_names()
        db = OpenSearchVectorSearch(
            self.opensearch_url,
            self.index_name,
            embeddings,
            text_field=field_names["content"],
            vector_field=field_names["vector"],
            engine=self.engine,
            space_type = self.get_distance_metric(),
            **self.auth_kwargs
        )

        # LangChain's OpenSearch add path creates a missing index with its internal default `space_type` ("l2")
        # unless `space_type` is explicitly forwarded at write time. Ensure index creation uses the KB metric.
        if allow_creation and not db.index_exists(self.index_name):
            try:
                db.create_index(
                    dimension=self.get_vector_size(),
                    index_name=self.index_name,
                    space_type=self.get_distance_metric(),
                )
            except RequestError as e:
                reason = e.info.get("error", {}).get("reason", "")
                if "does not support space type" in reason:
                    raise Exception(
                        "OpenSearch does not support Similarity Metric '{}' (space_type='{}') with k-NN engine '{}'. "
                        "Please choose another Similarity Metric.".format(
                            self.distance_metric.value,
                            self.get_distance_metric(),
                            self.engine,
                            self.INDEX_ENGINE_DKU_PROPERTY
                        )
                    ) from e
                elif reason is not None and reason != "":
                    raise Exception(reason) from e
                raise e

        return db

    def get_distance_metric(self) -> str:
        if self.distance_metric == DistanceMetric.DOT_PRODUCT:
            return "innerproduct"
        elif self.distance_metric == DistanceMetric.COSINE:
            return "cosinesimil"
        else:
            return "l2"

    def clear_index(self) -> None:
        db = self.get_db(None)
        if db.index_exists(self.index_name):
            db.delete_index(self.index_name)
        # see also custom AOSS handling on java side in ElasticSearchIndex and ElasticSearchOutput classes
        if self.is_amazon_opensearch_serverless:
            # AOSS needs time so that the deletion of the index does not race with indexing
            time.sleep(self.wait_delay_s)
        logger.info("Cleared OpenSearch index {}".format(self.index_name))

    def ensure_documents_are_indexed(self) -> None:
        if self.is_amazon_opensearch_serverless:
            logger.info("Waiting for documents to be indexed...")
            time.sleep(self.max_wait_delay_s)

    def _index_documents(self, documents_loader: VectorStoreLoader, vectorstore_db: "VectorStore", cleanup_mode: RecordManagerCleanupMode, source_id_key: str, batch_size: Optional[int] = None) -> None:
        if self.is_amazon_opensearch_serverless:
            raise Exception("AWS OpenSearch Serverless does not support smart sync or upsert modes")
        super(OpenSearchVectorStore, self)._index_documents(documents_loader, vectorstore_db, cleanup_mode, source_id_key, batch_size)

    @staticmethod
    def _get_search_type(query_settings):
        if query_settings.get("searchType") == "HYBRID":
            raise ValueError("Hybrid search is not supported with OpenSearch vector stores")
        return DkuRemoteVectorStore._get_search_type(query_settings)
